def main():
    SKILLS_DIR.mkdir(parents=True, exist_ok=True)
    print(f"🚀 EvolvixOS Skill Factory starting generation of {len(SKILLS_DATA)} skills...")
    created_count = 0

    for item in SKILLS_DATA:
        s_id = item["id"]
        s_name = item["name"]
        s_desc = item["description"]
        s_code = item["code"]

        s_dir = SKILLS_DIR / s_id
        s_dir.mkdir(parents=True, exist_ok=True)

        # 1. __init__.py
        init_file = s_dir / "__init__.py"
        with open(init_file, "w", encoding="utf-8") as f:
            f.write('"""' + s_name + ' EvolvixOS Skill."""\n')

        # 2. skill.json
        manifest = {
            "name": s_name,
            "description": s_desc,
            "version": "1.0.0",
            "free": True,
            "local": True,
            "cost": "$0.00"
        }
        json_file = s_dir / "skill.json"
        with open(json_file, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2)

        # 3. skill.py
        py_file = s_dir / "skill.py"
        full_py_code = "#!/usr/bin/env python3\n" + '"""' + s_name + ' - Free & Local EvolvixOS Skill."""\n' + "import json, sys, os, math, re\n\n" + s_code + "\n\nif __name__ == '__main__':\n    args = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}\n    print(json.dumps(Skill().run(args)))\n"
        with open(py_file, "w", encoding="utf-8") as f:
            f.write(full_py_code)

        created_count += 1

    print(f"✅ Successfully generated {created_count} skills in {SKILLS_DIR}")

if __name__ == "__main__":
    main()
